ston":"low","Jacksonville":"out"}},"7":{"note":"Deshler took down Priceville, but there are still ties at every point that will need to play out.","status":{"Lawrence County":"low","West Point":"low"}},"8":{"note":"This is a 9-team region and those usually take until the very last week to determine. However, Scottsboro, Good Hope and Cherokee County have separated themselves early at 3-0. The fourth spot is up for grabs. We''ll let the rest play out.","status":{"Crossville":"low","Hayden":"low"}}}},"3A":{"alignment":[1,2,3,4,5,6,7,8],"slots":[{"region":4,"place":1},{"region":1,"place":4},{"region":2,"place":2},{"region":3,"place":3},{"region":1,"place":1},{"region":4,"place":4},{"region":3,"place":2},{"region":2,"place":3},{"region":3,"place":1},{"region":2,"place":4},{"region":1,"place":2},{"region":4,"place":3},{"region":2,"place":1},{"region":3,"place":4},{"region":4,"place":2},{"region":1,"place":3},{"region":8,"place":1},{"region":5,"place":4},{"region":6,"place":2},{"region":7,"place":3},{"region":5,"place":1},{"region":8,"place":4},{"region":7,"place":2},{"region":6,"place":3},{"region":7,"place":1},{"region":6,"place":4},{"region":5,"place":2},{"region":8,"place":3},{"region":6,"place":1},{"region":7,"place":4},{"region":8,"place":2},{"region":5,"place":3}],"results":{"r1g0":{"home":"top"},"r1g1":{"home":"top"},"r1g2":{"home":"top"},"r1g3":{"home":"top"},"r1g4":{"home":"top"},"r1g5":{"home":"top"},"r1g6":{"home":"top"},"r1g7":{"home":"top"},"r1g8":{"home":"top"},"r1g9":{"home":"top"},"r1g10":{"home":"top"},"r1g11":{"home":"top"},"r1g12":{"home":"top"},"r1g13":{"home":"top"},"r1g14":{"home":"top"},"r1g15":{"home":"top"}},"projected":{"r1g15":"top","r2g7":"bottom","r3g3":"bottom","r4g1":"bottom","r5g0":"bottom","r1g10":"top","r2g5":"top","r3g2":"bottom","r1g8":"top","r2g4":"top","r1g7":"top","r2g3":"bottom","r3g1":"bottom","r4g0":"bottom","r1g2":"top","r2g1":"top","r3g0":"bottom","r1g5":"bottom","r2g2":"bottom","r1g14":"top","r1g4":"top","r1g6":"top","r1g3":"t